      const desc = document.createElement('span'); desc.className = 'steam-youtube-description'; desc.textContent = id === 'vovkzbtYBC8' ? 'Available March 20, 2025: Watch the official cinematic world premiere trailer of Assassin’s Creed Shadows.' : `YouTube · ${id}`;
      copy.append(title, views, desc); card.append(img, copy); return card;
